begin;
create temporary table test_results(name text,result text);
do $$
declare u uuid:=gen_random_uuid(); v uuid:=gen_random_uuid(); cust uuid:=gen_random_uuid(); s uuid; svc uuid; c uuid; ap uuid; ch uuid; op uuid:=gen_random_uuid(); cfg jsonb; slots jsonb; result jsonb; dt date:=current_date+1; link text; before_count int;
begin
 insert into auth.users(id,aud,role,email) values(u,'authenticated','authenticated','qa-owner-'||u||'@example.invalid'),(v,'authenticated','authenticated','qa-other-'||v||'@example.invalid'),(cust,'authenticated','authenticated','qa-client-'||cust||'@example.invalid');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated','iss','https://azbccqwjnzrzrhvnlncy.supabase.co/auth/v1')::text,true);
 perform public.kroner_api('create_shop');result:=public.kroner_api('workspace');s:=(result->'shop'->>'id')::uuid;link:=result->'shop'->>'slug';
 perform public.kroner_api('service','{"name":"Corte QA","price":4000,"duration":30}');select id into svc from kroner_private.services where shop=s;
 cfg:=jsonb_build_object('phone','+5534999991234','professional','QA','city','Teste','state','MG','timezone','America/Sao_Paulo','maxDays',21,'notice',0,'grid',15,'grace',15,'cancelMinutes',0,'creditFee',300,'debitFee',150,'week',(select jsonb_agg(jsonb_build_object('enabled',true,'open','08:30','close','22:00','lunchStart','12:00','lunchEnd','13:00')) from generate_series(0,6)));
 perform public.kroner_api('settings',jsonb_build_object('name','QA','cfg',cfg,'activate',true));
 slots:=public.kroner_api('slots',jsonb_build_object('slug',link,'services',jsonb_build_array(svc),'day',dt,'period','night'));
 assert jsonb_array_length(slots)>0,'Slots missing';assert slots->-1->>'label'='21:30','Last service exceeds closing';insert into test_results values('availability: end before closing','pass');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',cust,'role','authenticated','iss','https://azbccqwjnzrzrhvnlncy.supabase.co/auth/v1')::text,true);
 result:=public.kroner_api('book',jsonb_build_object('slug',link,'services',jsonb_build_array(svc),'day',dt,'period','night','start',slots->0->>'start','name','Cliente QA','phone','+5534999991234','request_id',op));ap:=(result->>'id')::uuid;
 result:=public.kroner_api('book',jsonb_build_object('slug',link,'services',jsonb_build_array(svc),'day',dt,'period','night','start',slots->0->>'start','name','Cliente QA','phone','+5534999991234','request_id',op));assert (result->>'id')::uuid=ap,'Duplicate booking';insert into test_results values('booking idempotency','pass');
 begin perform public.kroner_api('book',jsonb_build_object('slug',link,'services',jsonb_build_array(svc),'day',dt,'period','night','start',slots->0->>'start','name','Cliente QA','phone','+5534999991234','request_id',gen_random_uuid()));raise exception 'FAILED overlap allowed';exception when others then if sqlerrm like 'FAILED%' then raise;end if;end;insert into test_results values('overlapping booking rejected','pass');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated','iss','https://azbccqwjnzrzrhvnlncy.supabase.co/auth/v1')::text,true);
 perform public.kroner_api('finish',jsonb_build_object('id',ap,'payment','partial','amount',1000,'method','credit','paid_on',current_date,'settles_on',current_date,'request_id',gen_random_uuid()));
 select id into ch from kroner_private.charges where appointment=ap;
 assert (select amount from kroner_private.charges where id=ch)=4000;assert (select sum(amount) from kroner_private.payments where charge=ch)=1000;assert (select sum(fee) from kroner_private.payments where charge=ch)=30;insert into test_results values('partial payment fees on paid amount only','pass');
 op:=gen_random_uuid();perform public.kroner_api('pay',jsonb_build_object('charge',ch,'amount',3000,'method','pix','paid_on',current_date,'settles_on',current_date,'request_id',op));perform public.kroner_api('pay',jsonb_build_object('charge',ch,'amount',3000,'method','pix','paid_on',current_date,'settles_on',current_date,'request_id',op));assert (select sum(amount) from kroner_private.payments where charge=ch)=4000;insert into test_results values('payment retry does not duplicate','pass');

 result:=public.kroner_api('product','{"name":"Balm QA","cost":1000,"price":2000,"minimum":2}');c:=(result->>'id')::uuid;
 op:=gen_random_uuid();perform public.kroner_api('stock',jsonb_build_object('id',c,'kind','purchase','quantity',3,'paid',true,'method','pix','due',current_date,'request_id',op));
 perform public.kroner_api('stock',jsonb_build_object('id',c,'kind','purchase','quantity',3,'paid',true,'method','pix','due',current_date,'request_id',op));
 assert (select quantity from kroner_private.products where id=c)=3,'Stock doubled';
 perform public.kroner_api('stock',jsonb_build_object('id',c,'kind','sale','quantity',1,'paid',true,'method','credit','due',current_date,'settles_on',current_date,'request_id',gen_random_uuid()));
 assert (select quantity from kroner_private.products where id=c)=2;insert into test_results values('stock purchase/sale and retry','pass');
 begin perform public.kroner_api('stock',jsonb_build_object('id',c,'kind','sale','quantity',99,'paid',false,'method','pix','due',current_date,'request_id',gen_random_uuid()));raise exception 'FAILED negative stock';exception when others then if sqlerrm like 'FAILED%' then raise;end if;end;insert into test_results values('negative stock rejected','pass');
 op:=gen_random_uuid();result:=public.kroner_pos('sale',jsonb_build_object('request_id',op,'items',jsonb_build_array(jsonb_build_object('id',c,'quantity',1)),'discount',100,'payments','[{"method":"cash","amount":1000},{"method":"pix","amount":900}]'::jsonb));
 assert (select product_total-discount from kroner_private.sales where id=op)=1900;
 perform public.kroner_pos('refund',jsonb_build_object('request_id',gen_random_uuid(),'sale',op,'amount',1900,'method','pix','reason','Devolução QA','return_goods',true));
 assert (select quantity from kroner_private.products where id=c)=2;
 perform public.kroner_pos('close',jsonb_build_object('request_id',gen_random_uuid(),'day',current_date,'opening',2000,'counted',3000));
 insert into test_results values('PDV: split payment, discount, return and register close','pass');
 perform public.kroner_api('recurring','{"name":"Aluguel QA","amount":10000,"day":5,"variable":false}');
 perform public.kroner_api('generate_expenses',jsonb_build_object('month',current_date,'request_id',gen_random_uuid()));
 perform public.kroner_api('generate_expenses',jsonb_build_object('month',current_date,'request_id',gen_random_uuid()));
 assert (select count(*) from kroner_private.charges where shop=s and description='Aluguel QA')=1;insert into test_results values('recurring expense month idempotency','pass');
 select id into c from kroner_private.clients where shop=s and user_id=cust;
 perform public.kroner_api('membership',jsonb_build_object('client',c,'services',jsonb_build_array(svc),'weekday',extract(dow from (current_date+2))::int,'time','16:00','price',12000,'due_day',0));
 select id into c from kroner_private.memberships where shop=s;
 perform public.kroner_api('monthly_generate',jsonb_build_object('id',c,'month',current_date+2,'request_id',gen_random_uuid()));
 assert (select count(*) from kroner_private.appointments where membership=c)>=1;
 assert (select amount from kroner_private.charges where membership=c)=12000;insert into test_results values('monthly appointments and single charge','pass');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated','iss','https://azbccqwjnzrzrhvnlncy.supabase.co/auth/v1')::text,true);perform public.kroner_api('create_shop');result:=public.kroner_api('workspace');assert jsonb_array_length(result->'clients')=0;assert jsonb_array_length(result->'payments')=0;insert into test_results values('second shop cannot see first shop data','pass');
 perform set_config('request.jwt.claims','{}',true);
 begin perform public.kroner_api('workspace');raise exception 'FAILED anonymous workspace';exception when others then if sqlerrm like 'FAILED%' then raise;end if;end;insert into test_results values('anonymous private access denied','pass');
end $$;
select * from test_results;
rollback;
